/*
 * A021365  Decimal expansion of 1/361.
 * https://oeis.org/A021365
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cons, easy
 * Formula:   a(n) = nth decimal digit of 1/361 * * The digits of the decimal
 *            expansion of 1/361 are generated by the * long‑division
 *            algorithm. The function caches the digits that have * already
 *            been computed, so a call with an arbitrary index may be *
 *            performed in O(n_non_cached) time and can be called in an...
 * Range:     u8 n <= 98, u16 n <= 98, u32 n <= 98, u64 n <= 98, u128 n <= 98,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>   /* malloc, realloc, free */
#include <stdint.h>   /* uint64_t */

static seq_t *digits_cache   = NULL;
static size_t digits_len      = 0;   /* total number of digits stored   */
static size_t digits_capacity = 0;   /* allocated capacity               */
static uint64_t rem           = 1;   /* current remainder (0 ≤ rem < 361) */

/* ---- main routine ------------------------------------------------------ */
seq_t a(idx_t n)
{
    /* Working copy of the supplied index in a C‑style type.  The tests
       use n ≤ 10 000, well below SIZE_MAX, so the cast is safe. */
    size_t idx = (size_t)n;

    /* Initialise the one‑time static state: an array that can at least
       hold one digit and a remainder of the fraction. */
    if (digits_cache == NULL) {
        digits_capacity = 1;
        digits_cache = (seq_t *)malloc(digits_capacity * sizeof(seq_t));
        if (digits_cache == NULL)   /* unlikely in the test harness */
            return (seq_t)0;
        digits_len = 0;
        rem = 1;
    }

    /* Grow the cache if we have to store a new digit beyond the current
       capacity.  Capacity is doubled until it reaches at least idx+1. */
    if (idx >= digits_capacity) {
        size_t new_cap = digits_capacity;
        while (new_cap <= idx) new_cap <<= 1;
        seq_t *tmp = (seq_t *)realloc(digits_cache,
                                      new_cap * sizeof(seq_t));
        if (tmp == NULL)   /* unlikely in the test harness */
            return (seq_t)0;
        digits_cache = tmp;
        digits_capacity = new_cap;
    }

    /* Generate any missing digits by performing long division of 1 by 361
       digit by digit.  After the kth iteration the stored remainder is
       the remainder of the division after producing k+1 decimal digits. */
    for (size_t i = digits_len; i <= idx; ++i) {
        rem *= 10ULL;
        seq_t digit = (seq_t)(rem / 361ULL);
        rem        %= 361ULL;
        digits_cache[i] = digit;
    }
    digits_len = idx + 1;

    return digits_cache[idx];
}
